package com.example.rokidgeminisecretary;import org.json.*;public class OperationPolicyTest{static int n;static void ok(boolean b){if(!b)throw new AssertionError(n);n++;}public static void main(String[] a)throws Exception{long now=1000000;for(String[] pair:new String[][]{{"QUEUED","queued"},{"RECEIVED","received"},{"RUNNING","running"},{"ANSWERED","completed"},{"COMPLETED","completed"},{"FAILED","failed"},{"UNCONFIRMED","needs_check"},{"garbage","needs_check"},{"AWAITING_CONFIRMATION","confirmation"},{"DEFERRED","deferred"},{"CANCELLED","cancelled"}}){JSONObject row=OperationStatusPolicy.card("conversation","id","title",pair[0],now,now);ok(row.getString("phase").equals(pair[1]));}ok(OperationStatusPolicy.card("conversation","id","title","RUNNING",now-300001,now).getString("phase").equals("needs_check"));ok(OperationStatusPolicy.card("conversation","id","title","RUNNING",now+1,now).getString("phase").equals("needs_check"));ok(!OperationStatusPolicy.card("conversation","id","title","UNCONFIRMED",now,now).getBoolean("terminal"));ok(OperationStatusPolicy.card("meeting","id","title","RUNNING",now-600000,now).getString("phase").equals("running"));JSONArray history=new JSONArray().put(new JSONObject().put("key","old").put("tracked",true).put("requestState","RUNNING"));for(int i=0;i<20;i++)history.put(new JSONObject().put("key","done"+i).put("tracked",true).put("requestState","ANSWERED"));String original=history.toString();JSONArray visible=OperationStatusPolicy.conversationRows(history,12);ok(visible.length()==12);ok(visible.getJSONObject(0).getString("key").equals("old"));ok(visible.getJSONObject(1).getString("key").equals("done19"));ok(history.toString().equals(original));visible.getJSONObject(0).put("key","changed");ok(history.getJSONObject(0).getString("key").equals("old"));ok(OperationStatusPolicy.conversationRows(history,0).length()==0);ok(OperationStatusPolicy.conversationRows(new JSONArray().put("corrupt").put(new JSONObject().put("key","legacy")),12).getJSONObject(0).getString("key").equals("legacy"));ok(!OperationStatusPolicy.card("conversation","id","title","QUEUED",now-300001,now).getString("detail").isEmpty());ok(OperationStatusPolicy.card("conversation","id","title","ANSWERED",now-600000,now).getString("detail").isEmpty());ok(!OperationStatusPolicy.card("meeting","id","title","RUNNING",now-600000,now).getBoolean("terminal"));ok(OperationStatusPolicy.card(null,null,null,null,0,now).getString("phase").equals("needs_check"));
 System.out.println("PASS "+n+" operation status checks");}}